contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        // Fresh contract: MinSum is 1 ether, so choose an amount strictly below it.
        require(amount > 0 && amount < c.MinSum());
        require(address(this).balance >= amount);

        c.Put{value: amount}(0);

        uint balBefore = address(c).balance;
        (uint recBalBefore, ) = c.Acc(address(this));

        // Collect must succeed without reverting...
        c.Collect(amount);

        uint balAfter = address(c).balance;
        (uint recBalAfter, ) = c.Acc(address(this));

        // ...and must not change the contract's Ether or the recorded balance,
        // because acc.balance < MinSum blocks the withdrawal.
        assert(balAfter == balBefore && recBalAfter == recBalBefore);
    }

    receive() external payable {}
}

